import {initializeLocalization,setLanguage,currentLanguage,languageControl,translateDOM,languageLoadError,t} from './i18n.js?v=20261112-113';
const host=document.getElementById('credit-language'),error=document.getElementById('language-error');
// Page-specific attribution stays localized without changing the shared catalog.
const creditCopy={
 chamberThermistorHeading:{"ja": "チャンバー温度センサーの交換", "en": "Chamber thermistor replacement", "cs": "Výměna komorového termistoru", "de": "Kammerthermistor austauschen"},
 chamberThermistorReference:{"ja": "公式ガイドに沿った22手順です。温度センサーと260 mmのケーブル経路、2極の右角端子は説明用の独自モデルです。内部寸法や配線形状には推定を含みます。参考形状はCC BY-SA 4.0、作図・表示コードはMITです。写真と元のCADは、それぞれの条件を引き継ぎます。", "en": "The procedure follows the official guide in 22 steps. The sensor, 260 mm cable route and two-position right-angle header are independently authored teaching models. Internal dimensions and routing include estimates. Reference geometry uses CC BY-SA 4.0; original model and display code use MIT. Photographs and native CAD retain their respective terms.", "cs": "Postup má 22 kroků podle oficiálního návodu. Snímač, trasa kabelu 260 mm a dvoupólový pravoúhlý konektor jsou samostatně vytvořené výukové modely. Vnitřní rozměry a vedení kabelu obsahují odhady. Referenční geometrie je pod CC BY-SA 4.0, původní modelovací a zobrazovací kód pod MIT. Fotografie a původní CAD si ponechávají vlastní podmínky.", "de": "Das Verfahren folgt der offiziellen Anleitung in 22 Schritten. Sensor, 260-mm-Kabelweg und zweipoliger abgewinkelter Platinenstecker sind eigenständig erstellte Lehrmodelle. Innenmaße und Kabelführung enthalten Annahmen. Für die Referenzgeometrie gilt CC BY-SA 4.0, für den ursprünglichen Modellierungs- und Darstellungscode MIT. Fotos und ursprüngliches CAD behalten ihre jeweiligen Bedingungen."},

 molexBoard:{"ja":"LoveBoardの白い単列端子はCLIK-Mate 1.5 mm用の参照モデルです。2〜4極のプラグは502578、基板側は502584・502585シリーズに対応します。内部形状、ラッチの変形、基板上の配置には推定を含みます。黒いヒーター端子はMicro-Fit 3.0です。","en":"The white single-row LoveBoard connectors are reference models for 1.5 mm CLIK-Mate parts. The 2–4-position plugs correspond to 502578 and the board headers to 502584 and 502585. Internal details, latch deformation and board registration include estimates. The black heater connector is Micro-Fit 3.0.","cs":"Bílé jednořadé konektory LoveBoard jsou referenční modely dílů CLIK-Mate s roztečí 1,5 mm. Zástrčky se 2–4 pozicemi odpovídají řadě 502578, konektory desky řadám 502584 a 502585. Vnitřní detaily, deformace západky a poloha na desce obsahují odhady. Černý konektor topení je Micro-Fit 3.0.","de":"Die weißen einreihigen LoveBoard-Steckverbinder sind Referenzmodelle für CLIK-Mate mit 1,5 mm Raster. Die 2- bis 4-poligen Stecker entsprechen 502578, die Platinenstecker 502584 und 502585. Innere Details, Rastverformung und Platinenposition enthalten Annahmen. Der schwarze Heizungsstecker ist Micro-Fit 3.0."},
 fanAnatomyHeading:{"ja": "チャンバーファンの内部形状", "en": "Chamber fan reference internals", "cs": "Referenční vnitřní díly komorového ventilátoru", "de": "Referenz für das Innere des Kammerlüfters"},
 fanAnatomy:{"ja": "元のCADの枠に、独自作図した7枚の羽根、中心部、裏側の支えを補っています。内部寸法は公式写真を参考にした推定値です。加工用モデルではありません。", "en": "The original CAD frames are supplemented with seven independently authored blades, a hub and rear supports. Internal dimensions are estimates based on official photographs. This is not a manufacturing model.", "cs": "Původní CAD rámy doplňuje sedm samostatně vytvořených lopatek, střed a zadní podpěry. Vnitřní rozměry jsou odhady podle oficiálních fotografií. Nejde o výrobní model.", "de": "Die ursprünglichen CAD-Rahmen werden um sieben eigenständig erstellte Flügel, eine Nabe und hintere Streben ergänzt. Innenmaße sind anhand offizieller Fotos geschätzt. Dies ist kein Fertigungsmodell."},
 j13Heading:{"ja": "メインケーブル端子の参照モデル", "en": "Main cable connector reference models", "cs": "Referenční modely konektoru hlavního kabelu", "de": "Referenzmodelle des Hauptkabel-Steckverbinders"},
 j13:{"ja": "22極のメインケーブル端子（5031492200／5031542290）は独自作図した表示用モデルです。固定金具を含む金属部と樹脂部を分け、共通の配線・ラッチ動作に接続しています。内部形状と基板上の配置には推定を含みます。", "en": "The 22-position main cable connectors (5031492200 / 5031542290) are independently authored display models. Metal contacts and fixing features are separated from resin and use the shared cable and latch motion. Internal details and board registration include estimates.", "cs": "Konektory hlavního kabelu s 22 pozicemi (5031492200 / 5031542290) jsou samostatně vytvořené modely pro zobrazení. Kovové kontakty a upevňovací prvky jsou odděleny od plastu a používají společný pohyb kabelu a západky. Vnitřní detaily a poloha na desce obsahují odhady.", "de": "Die 22-poligen Hauptkabel-Steckverbinder (5031492200 / 5031542290) sind eigenständig erstellte Darstellungsmodelle. Metallkontakte und Befestigungselemente sind vom Kunststoff getrennt und verwenden die gemeinsame Kabel- und Rastnasenbewegung. Innere Details und die Platinenposition enthalten Annahmen."},
 doorHandleHeading:{"ja":"ネジ固定式ドアハンドルの表示モデル","en":"Screw-mounted door handle visualization","cs":"Zobrazení kliky dveří se šroubovým upevněním","de":"Darstellung des verschraubten Türgriffs"},
 doorHandleModel:{"ja":"現行のネジ固定式ハンドルは、Prusa ResearchのCORE One公式CAD（OCL v1）の金属部から、独立した粘着パッド2個だけを除いた表示です。元の形状は接着版・元の構成・アップグレード用に保持しています。2本のM3x8rTも元CADと同一形状です。プレートは公式写真・手順とCADの穴位置を参考に新たに作成した組立説明用モデルで、公式プレートCADではありません。","en":"The current screw-mounted handle uses Prusa Research’s CORE One CAD metal body (OCL v1), omitting only two separate adhesive pads. The original geometry is retained for glued, original and upgrade views. Both M3x8rT screws copy the native CAD geometry. The plate is a separately authored assembly illustration based on official photographs, the guide and CAD hole positions, not an official plate CAD model.","cs":"Současná klika se šroubovým upevněním používá kovovou část oficiálního CAD CORE One společnosti Prusa Research (OCL v1), pouze bez dvou samostatných lepicích podložek. Původní geometrie zůstává pro lepenou variantu, původní sestavu a upgrade. Oba šrouby M3x8rT kopírují původní CAD. Destička je samostatně vytvořené znázornění montáže podle oficiálních fotografií, návodu a poloh otvorů v CAD, nikoli oficiální CAD destičky.","de":"Der aktuelle verschraubte Griff verwendet den Metallkörper aus dem offiziellen CORE-One-CAD von Prusa Research (OCL v1), lediglich ohne zwei separate Klebepads. Die ursprüngliche Geometrie bleibt für Klebe-, Original- und Upgrade-Ansichten erhalten. Beide M3x8rT-Schrauben übernehmen die ursprüngliche CAD-Geometrie. Die Platte ist eine eigenständig erstellte Montageillustration anhand offizieller Fotos, der Anleitung und der CAD-Bohrungspositionen, kein offizielles CAD-Modell der Platte."},
 doorHandleLimits:{"ja":"幅8 mm、板厚1 mm、端の余長15 mm、ボス外径5.5 mm・高さ2.3 mmは表示用の仮定です。製造・検査用データではありません。参照写真にOCLを適用するものではありません。","en":"The 8 mm width, 1 mm thickness, 15 mm end margin, 5.5 mm boss outer diameter and 2.3 mm boss height are display assumptions. This is not manufacturing or inspection data. OCL is not assigned to the reference photographs.","cs":"Šířka 8 mm, tloušťka 1 mm, přesah na koncích 15 mm, vnější průměr sloupků 5.5 mm a jejich výška 2.3 mm jsou předpoklady pro zobrazení. Nejde o výrobní ani kontrolní data. Na referenční fotografie se nepřiřazuje licence OCL.","de":"8 mm Breite, 1 mm Dicke, 15 mm Randzugabe an den Enden, 5.5 mm Außendurchmesser und 2.3 mm Höhe der Säulen sind Darstellungsannahmen. Dies sind keine Fertigungs- oder Prüfdaten. Den Referenzfotos wird keine OCL-Lizenz zugewiesen."},
 teHeading:{"ja": "LCDコネクターの参照モデル", "en": "LCD connector reference models", "cs": "Referenční modely LCD konektorů", "de": "Referenzmodelle der LCD-Steckverbinder"},
 te:{"ja": "LCDコネクター（2-215083-4／9-338069-4）は、公表寸法と部品構成を参考に独自作図した表示用モデルです。内部のばね・成形形状には推定を含みます。メーカーのCAD形状は含みません。", "en": "The LCD connectors (2-215083-4 / 9-338069-4) are independently authored display models based on published dimensions and component construction. Internal springs and moulding details include estimates. Manufacturer CAD geometry is not included.", "cs": "LCD konektory (2-215083-4 / 9-338069-4) jsou samostatně vytvořené modely pro zobrazení podle zveřejněných rozměrů a konstrukce dílů. Vnitřní pružiny a detaily výlisků obsahují odhady. Geometrie CAD výrobce není součástí modelů.", "de": "Die LCD-Steckverbinder (2-215083-4 / 9-338069-4) sind eigenständig erstellte Darstellungsmodelle auf Basis veröffentlichter Maße und des Bauteilaufbaus. Innere Federn und Formdetails enthalten Annahmen. CAD-Geometrie des Herstellers ist nicht enthalten."},
 scopeHeading:{en:'Terms for each asset',cs:'Podmínky jednotlivých podkladů',de:'Nutzungsbedingungen der einzelnen Inhalte'},
 scope:{en:'Licenses apply to each asset separately. CAD, code, photographs, screen artwork and fonts retain their respective providers’ terms.',cs:'Licence se vztahují na jednotlivé podklady samostatně. CAD, kód, fotografie, grafika obrazovek a písma podléhají podmínkám příslušných poskytovatelů.',de:'Lizenzen gelten für die einzelnen Inhalte. Für CAD, Code, Fotos, Bildschirmgrafiken und Schriften gelten die jeweiligen Bedingungen ihrer Anbieter.'},
 ocl:{en:'CAD and derived meshes designated OCL v1 retain that license’s separate terms for non-commercial and business use.',cs:'CAD a odvozené sítě označené OCL v1 podléhají této licenci, která rozlišuje nekomerční a podnikatelské použití.',de:'CAD und abgeleitete Netze mit der Angabe OCL v1 unterliegen deren getrennten Bedingungen für nichtkommerzielle und geschäftliche Nutzung.'},
 gpl:{en:'GPL v2.0 for printed parts and GPL v3.0 for firmware-derived code are separate designations. Each license sets requirements for attribution, modification notices and corresponding source.',cs:'GPL v2.0 pro tištěné díly a GPL v3.0 pro kód odvozený z firmwaru jsou samostatná označení. Každá licence stanovuje požadavky na uvedení autorů, změn a odpovídajícího zdrojového kódu.',de:'GPL v2.0 für Druckteile und GPL v3.0 für aus Firmware abgeleiteten Code sind getrennte Angaben. Jede Lizenz legt Anforderungen an Urhebervermerke, Änderungsvermerke und den entsprechenden Quelltext fest.'},
 photoHeading:{en:'Official photographs and manuals',cs:'Oficiální fotografie a návody',de:'Offizielle Fotos und Anleitungen'},
 photos:{en:'Official photographs, manual text and their translations remain copyrighted by their respective owners. Linking to or downloading an image does not grant permission to redistribute photographs, adaptations or textures.',cs:'Práva k oficiálním fotografiím, textům návodů a jejich překladům náleží příslušným vlastníkům. Odkaz na obrázek ani jeho stažení neuděluje oprávnění k dalšímu šíření fotografií, úprav nebo textur.',de:'Die Rechte an offiziellen Fotos, Anleitungstexten und deren Übersetzungen liegen bei den jeweiligen Rechteinhabern. Ein Bildlink oder Download erteilt keine Erlaubnis zur Weiterverbreitung von Fotos, Bearbeitungen oder Texturen.'},
 molexHeading:{"ja":"CLIK-Mate端子の参照モデル","en":"CLIK-Mate connector reference models","cs":"Referenční modely konektorů CLIK-Mate","de":"CLIK-Mate-Steckverbinder als Referenzmodelle"},
 molex:{"ja":"2〜4極のCLIK-Mate端子7モデルは独自作図した表示用モデルです。内部の受け・ばね形状と基板上の配置には推定を含みます。モデルはCC BY-SA 4.0、作図コードはMITです。メーカーのCAD形状は含みません。","en":"The seven 2–4-position CLIK-Mate connector models are independently authored display references. Internal receiving and spring details and board registration include estimates. Models use CC BY-SA 4.0; producer code uses MIT. Manufacturer CAD geometry is not included.","cs":"Sedm modelů konektorů CLIK-Mate se 2–4 pozicemi je samostatně vytvořeno pro zobrazení. Vnitřní úložné a pružinové detaily i poloha na desce obsahují odhady. Modely jsou pod CC BY-SA 4.0, zdrojový kód pod MIT. Geometrie CAD výrobce není zahrnuta.","de":"Die sieben 2- bis 4-poligen CLIK-Mate-Steckverbinder sind eigenständig erstellte Darstellungsmodelle. Innere Aufnahme- und Federdetails sowie die Platinenposition enthalten Annahmen. Für die Modelle gilt CC BY-SA 4.0, für den Erzeugungscode MIT. Hersteller-CAD-Geometrie ist nicht enthalten."},
 bitmapHeading:{en:'LCD bitmap lettering',cs:'Bitmapová písma LCD',de:'LCD-Bitmap-Schriften'},
 bitmap:{en:'Latin LCD glyphs derive from Liberation Mono; Katakana and Japanese punctuation derive from Migu 1M. The font licenses apply to these glyphs separately from the CC BY-NC-SA 4.0 license for screen icons and artwork.',cs:'Latinské znaky LCD pocházejí z Liberation Mono; katakana a japonská interpunkce z Migu 1M. Na tyto znaky se vztahují licence písem, odděleně od CC BY-NC-SA 4.0 pro ikony a grafiku obrazovek.',de:'Die lateinischen LCD-Zeichen stammen aus Liberation Mono, Katakana und japanische Satzzeichen aus Migu 1M. Für diese Zeichen gelten die Schriftlizenzen, getrennt von CC BY-NC-SA 4.0 für Bildschirmsymbole und Grafiken.'},
 independence:{en:'An independent community learning guide. Company names and trademarks identify sources and parts; they do not imply official endorsement.',cs:'Nezávislý komunitní výukový průvodce. Názvy společností a ochranné známky označují zdroje a díly; nevyjadřují oficiální podporu těchto společností.',de:'Ein unabhängiger Lernleitfaden aus der Community. Firmennamen und Marken kennzeichnen Quellen und Teile; sie bedeuten keine offizielle Empfehlung durch diese Unternehmen.'}
};
const japaneseCopy=new Map([...document.querySelectorAll('[data-credit-copy]')].map(node=>[node.dataset.creditCopy,node.textContent]));
let maintenanceTasks;
const coverageTemplate='清掃・注油、詰まりの点検・除去、ベルト調整、ホットエンド・Prusa Nozzle・ファン・LoveBoardの交換を{tasks}作業・{stages}段階で案内します。工具の接触や締め付けトルクは3D表示から確認できません。';
const localizeCredits=()=>{
 for(const node of document.querySelectorAll('[data-credit-copy]'))node.textContent=creditCopy[node.dataset.creditCopy]?.[currentLanguage()]||japaneseCopy.get(node.dataset.creditCopy);
 if(maintenanceTasks){
  const coverage=document.getElementById('maintenance-coverage');
  coverage.textContent=t(coverageTemplate.replace('{tasks}',maintenanceTasks.length).replace('{stages}',maintenanceTasks.reduce((total,task)=>total+task.steps.length,0)));
  coverage.hidden=false;
 }
};
const showError=reason=>{error.hidden=false;error.textContent=languageLoadError(reason?.requestedLanguage||currentLanguage());};
await initializeLocalization({flows:{},parts:{},plan:{}}).catch(showError);
host.innerHTML=languageControl();translateDOM(document.documentElement);localizeCredits();
// Keep the count coupled to the same task exports used by the maintenance UI.
// If this optional data cannot load, omit the count instead of showing stale totals.
import('./maintenance-data.js?v=20261113-118').then(({SERVICE_TASKS})=>{maintenanceTasks=SERVICE_TASKS;localizeCredits();}).catch(()=>{});
host.addEventListener('change',async event=>{
 const select=event.target;if(!select.matches('[data-language]'))return;select.disabled=true;
 try{if(await setLanguage(select.value)){error.hidden=true;translateDOM(document.documentElement);localizeCredits();}}
 catch{showError();}
 finally{select.disabled=false;select.value=currentLanguage();}
});
